package com.casegen.ai.proposal.review;
import static org.junit.jupiter.api.Assertions.*;
import com.casegen.ai.message.domain.AiMessage;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;
import static org.mockito.Mockito.*;
class AiProposalBatchPromptBuilderTest {
 @Test void promptContainsWholeCatalogSafetyRulesLimitsAndExactSchema(){AiMessage source=mock(AiMessage.class);when(source.getContent()).thenReturn("Review inventory");UUID existing=UUID.randomUUID();AiUmlReviewSnapshot snapshot=new AiUmlReviewSnapshot(UUID.randomUUID(),"Project",UUID.randomUUID(),"Model",4,null,true,new AiUmlReviewSnapshot.Counts(0,1,0,0,0),List.of(),List.of(new AiUmlReviewSnapshot.ClassifierEntry(existing,"Producto",null,null,com.casegen.modeling.domain.ClassifierKind.CLASS,com.casegen.modeling.domain.Visibility.PUBLIC,false,false,false)),List.of(),List.of(),List.of(),List.of(),List.of());String system=new AiProposalBatchPromptBuilder(JsonMapper.builder().build()).build(source,snapshot).systemInstruction();String content=new AiProposalBatchPromptBuilder(JsonMapper.builder().build()).build(source,snapshot).messages().getFirst().content();assertTrue(system.contains("TODO el catalogo"));assertTrue(system.contains("Nunca inventes UUID"));assertTrue(system.contains("PK, FK"));assertTrue(system.contains("items.length <= 12"));assertTrue(system.contains("1-2 ADD_CLASSIFIER"));assertTrue(system.contains("PrimitiveType=STRING|INTEGER|BOOLEAN|REAL|UNLIMITED_NATURAL"));assertTrue(system.contains("AssociationEndOwnership=ASSOCIATION|CLASSIFIER"));assertTrue(system.contains("UPDATE_CLASSIFIER no incluye kind"));assertTrue(system.contains("\"ownerRef\""));assertTrue(system.contains("\"elementId\""));assertTrue(system.contains("\"proposalRef\""));assertTrue(system.contains("ownerClassifierId is PROHIBITED"));for(String type:List.of("ADD_CLASSIFIER:","ADD_ATTRIBUTE existing owner:","ADD_OPERATION:","ADD_ASSOCIATION existing-to-new:","ADD_GENERALIZATION:","ADD_REALIZATION:","UPDATE_CLASSIFIER:","UPDATE_ATTRIBUTE:"))assertTrue(system.contains(type));assertTrue(content.contains(existing.toString()));assertTrue(content.contains("Producto"));assertTrue(content.contains("\"truncated\":true"));}
}
